            "content": "> **Version:** v3.8.44\r\n> &#x2A;*Last updated:** 2026-07-03\r\n> &#x2A;*Audience:** Engineers adding, maintaining, or debugging embedded services (9Router, CLIProxyAPI, Mux, Bifrost)."
